+func encodeShapeIndex(t *testing.T, index *ShapeIndex) []byte {
+	t.Helper()
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatalf("Encode() = %v", err)
+	}
+	return buf.Bytes()
+}
+
+func roundTripShapeIndex(t *testing.T, index *ShapeIndex) *ShapeIndex {
+	t.Helper()
+	data := encodeShapeIndex(t, index)
+	got := NewShapeIndex()
+	if err := got.Decode(bytes.NewReader(data)); err != nil {
+		t.Fatalf("Decode() = %v", err)
+	}
+	return got
+}
+
+func checkShapesEqual(t *testing.T, id int32, want, got Shape) {
+	t.Helper()
+	if _, ok := want.(*edgeVectorShape); ok {
+		// Test-only shapes decode as a generic edge-list shape.
+		if _, ok := got.(*genericShape); !ok {
+			t.Errorf("shape %d: type = %T, want *genericShape", id, got)
+		}
+	} else if reflect.TypeOf(want) != reflect.TypeOf(got) {
+		t.Errorf("shape %d: type = %T, want %T", id, got, want)
+	}
+	if got.Dimension() != want.Dimension() {
+		t.Errorf("shape %d: Dimension() = %d, want %d", id, got.Dimension(), want.Dimension())
+	}
+	if got.NumEdges() != want.NumEdges() {
+		t.Fatalf("shape %d: NumEdges() = %d, want %d", id, got.NumEdges(), want.NumEdges())
+	}
+	for e := 0; e < want.NumEdges(); e++ {
+		if got.Edge(e) != want.Edge(e) {
+			t.Errorf("shape %d: Edge(%d) = %v, want %v", id, e, got.Edge(e), want.Edge(e))
+		}
+		if got.ChainPosition(e) != want.ChainPosition(e) {
+			t.Errorf("shape %d: ChainPosition(%d) = %v, want %v", id, e, got.ChainPosition(e), want.ChainPosition(e))
+		}
+	}
+	if got.NumChains() != want.NumChains() {
+		t.Fatalf("shape %d: NumChains() = %d, want %d", id, got.NumChains(), want.NumChains())
+	}
+	for c := 0; c < want.NumChains(); c++ {
+		if got.Chain(c) != want.Chain(c) {
+			t.Errorf("shape %d: Chain(%d) = %v, want %v", id, c, got.Chain(c), want.Chain(c))
+		}
+	}
+	if got.ReferencePoint() != want.ReferencePoint() {
+		t.Errorf("shape %d: ReferencePoint() = %v, want %v", id, got.ReferencePoint(), want.ReferencePoint())
+	}
+	if got.IsEmpty() != want.IsEmpty() || got.IsFull() != want.IsFull() {
+		t.Errorf("shape %d: IsEmpty/IsFull = %v/%v, want %v/%v", id,
+			got.IsEmpty(), got.IsFull(), want.IsEmpty(), want.IsFull())
+	}
+}
+
+// checkIndexesEqual compares two indexes without building the second one.
+func checkIndexesEqual(t *testing.T, want, got *ShapeIndex) {
+	t.Helper()
+	want.Build()
+	if !got.IsFresh() {
+		t.Fatalf("decoded index is not fresh")
+	}
+	if got.Len() != want.Len() {
+		t.Fatalf("Len() = %d, want %d", got.Len(), want.Len())
+	}
+	if got.nextID != want.nextID {
+		t.Errorf("nextID = %d, want %d", got.nextID, want.nextID)
+	}
+	for id := int32(0); id < want.nextID; id++ {
+		ws, gs := want.Shape(id), got.Shape(id)
+		if (ws == nil) != (gs == nil) {
+			t.Fatalf("Shape(%d) = %v, want %v", id, gs, ws)
+		}
+		if ws != nil {
+			checkShapesEqual(t, id, ws, gs)
+		}
+	}
+	if !slices.Equal(got.cells, want.cells) {
+		t.Fatalf("cells = %v, want %v", got.cells, want.cells)
+	}
+	wi, gi := want.Iterator(), got.Iterator()
+	for ; !wi.Done(); wi.Next() {
+		if gi.Done() || gi.CellID() != wi.CellID() {
+			t.Fatalf("iterator mismatch at %v", wi.CellID())
+		}
+		wc, gc := wi.IndexCell(), gi.IndexCell()
+		if len(wc.shapes) != len(gc.shapes) {
+			t.Fatalf("cell %v: %d clipped shapes, want %d", wi.CellID(), len(gc.shapes), len(wc.shapes))
+		}
+		for i := range wc.shapes {
+			if !reflect.DeepEqual(wc.shapes[i], gc.shapes[i]) {
+				t.Errorf("cell %v: clipped %d = %+v, want %+v", wi.CellID(), i, gc.shapes[i], wc.shapes[i])
+			}
+		}
+		gi.Next()
+	}
+	if !gi.Done() {
+		t.Errorf("decoded index has extra cells")
+	}
+}
